const grid=document.querySelector('#grid'),search=document.querySelector('#search'),dialog=document.querySelector('#detail');
let category='Alles';
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function link(url,label,cls=''){return url?`<a class="${cls}" href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer">${label} <span aria-hidden="true">↗</span></a>`:'';}
function render(){const query=search.value.toLocaleLowerCase('nl'); const filtered=projects.filter(p=>(category==='Alles'||p.category===category)&&[p.name,p.description,...p.stack].join(' ').toLocaleLowerCase('nl').includes(query));grid.innerHTML=filtered.map(p=>`<article class="card"><button class="poster ${p.theme}" data-project="${projects.indexOf(p)}" aria-label="Bekijk ${escapeHTML(p.name)}"><span class="poster-meta">${escapeHTML(p.category)} / ${String(projects.indexOf(p)+1).padStart(2,'0')}</span><span class="artwork" aria-hidden="true">${p.symbol}</span><span class="poster-title">${escapeHTML(p.name)}</span><span class="poster-arrow" aria-hidden="true">↗</span></button><div class="cardbody"><div class="cardhead"><h3>${escapeHTML(p.name)}</h3>${p.pending?'<span class="status">Aanvullen</span>':''}</div><p>${escapeHTML(p.description)}</p><div class="tags">${p.stack.slice(0,3).map(t=>`<span>${escapeHTML(t)}</span>`).join('')}</div><div class="cardlinks">${link(p.url,'Open app')}${link(p.source,'Broncode')}<button data-project="${projects.indexOf(p)}">Details <span aria-hidden="true">+</span></button></div></div></article>`).join('');document.querySelector('#empty').hidden=!!filtered.length;document.querySelector('#results').textContent=`${filtered.length} projecten gevonden`;}
document.querySelector('#total').textContent=String(projects.length).padStart(2,'0');
document.querySelector('.filters').innerHTML=['Alles','Creatief','Spellen','Tools','Experimenten'].map(c=>`<button aria-pressed="${c==='Alles'}" data-filter="${c}">${c}</button>`).join('');
document.querySelector('.filters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;category=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));render();});
search.addEventListener('input',render);
grid.addEventListener('click',e=>{const b=e.target.closest('[data-project]');if(!b)return;const p=projects[Number(b.dataset.project)];document.querySelector('#detail-content').innerHTML=`<p class="eyebrow">${escapeHTML(p.category)}</p><h2 id="dialog-title">${escapeHTML(p.name)}</h2><p class="dialogdesc">${escapeHTML(p.description)}</p><h3>Zo gebruik je het</h3><p>${escapeHTML(p.usage)}</p><h3>Tech stack</h3><div class="tags">${p.stack.length?p.stack.map(s=>`<span>${escapeHTML(s)}</span>`).join(''):'<p>Nog niet vastgelegd.</p>'}</div><h3>Alle links</h3><div class="detaillinks">${link(p.url,'Open website')}${link(p.source,'Bekijk broncode')}${link(p.docs|| (p.source?p.source+'#readme':null),'Handleiding / README')}</div>${!p.url||!p.source?'<p class="missing">'+[!p.url?'Live link ontbreekt nog.':'',!p.source?'Broncodelink ontbreekt nog.':''].filter(Boolean).join(' ')+'</p>':''}`;dialog.setAttribute('aria-labelledby','dialog-title');dialog.showModal();});
document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});render();
